import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../accounts_providers.dart';

class AccountsDashboard extends ConsumerWidget { const AccountsDashboard({super.key}); @override Widget build(BuildContext c, WidgetRef r) => Scaffold(appBar: AppBar(title: const Text('Accounts & Collections')), body: r.watch(invoicesProvider).when(loading: () => const Center(child: CircularProgressIndicator()), error: (e, _) => Center(child: Text('$e')), data: (items) => ListView(padding: const EdgeInsets.all(16), children: [Text('${items.length} invoices'), const SizedBox(height: 12), FilledButton(onPressed: () => c.go('/accounts/invoices'), child: const Text('View invoices')), OutlinedButton(onPressed: () => c.go('/accounts/invoices/new'), child: const Text('Create invoice')), OutlinedButton(onPressed: () => c.go('/accounts/approvals'), child: const Text('Approvals'))]))); }
class InvoiceCreateScreen extends ConsumerWidget { const InvoiceCreateScreen({super.key}); @override Widget build(BuildContext c, WidgetRef r) => Scaffold(appBar: AppBar(title: const Text('Create invoice')), body: const Center(child: Text('Create invoice details from a customer account.'))); }
class InvoiceListScreen extends ConsumerWidget { const InvoiceListScreen({super.key, this.contactId}); final String? contactId; @override Widget build(BuildContext c, WidgetRef r) => Scaffold(appBar: AppBar(title: const Text('Invoices')), body: r.watch(invoicesProvider).when(loading: () => const Center(child: CircularProgressIndicator()), error: (e, _) => Center(child: Text('$e')), data: (items) => ListView(children: items.map((item) => ListTile(title: Text(item.number), subtitle: Text(item.status), trailing: Text(item.outstanding.toStringAsFixed(2)), onTap: () => c.go('/accounts/invoices/${item.id}'))).toList()))); }
class InvoiceDetailScreen extends ConsumerWidget { const InvoiceDetailScreen({super.key, required this.id}); final String id; @override Widget build(BuildContext c, WidgetRef r) => Scaffold(appBar: AppBar(title: const Text('Invoice')), body: FutureBuilder(future: r.read(accountsRepositoryProvider).invoice(id), builder: (c, snapshot) { if (!snapshot.hasData) return const Center(child: CircularProgressIndicator()); final invoice = Map<String, dynamic>.from((snapshot.data as Map)['invoice'] as Map); return ListView(padding: const EdgeInsets.all(16), children: [Text('${invoice['invoice_number'] ?? id}', style: Theme.of(c).textTheme.headlineSmall), Text('Status: ${invoice['status'] ?? ''}'), Text('Total: ${invoice['total_amount'] ?? ''}'), OutlinedButton(onPressed: () => c.go('/accounts/invoices/$id/edit'), child: const Text('Edit invoice'))]); })); }
